def log_activity(message):
    global current_log_message
    current_time = datetime.now().strftime("[%I:%M %p]")
    log_entry = f"{current_time} {message}\n"
    current_log_message = f"{current_time}{message}"
    with open("activity.log", "a") as log_file:
        log_file.write(log_entry)
    print(log_entry.strip())
def send_completion_email(sender_email, receiver_email, file_name, your_smtp_password,password):
    smtp_server = "smtp.gmail.com"
    smtp_port = 587    # <-- Replace this
    
    subject = "Image Encryption Completed Successfully"
    body = f"Hello,\n\nThe encryption process for the file '{file_name}' has been completed successfully.\n\nBest regards,\nSecure Encryptor System \n your Encryption password is:{password}"
    
    try:
        # Set up the email headers
        msg = MIMEMultipart()
        msg['From'] = sender_email
        msg['To'] = receiver_email
        msg['Subject'] = subject
        msg.attach(MIMEText(body, 'plain'))
        
        # Connect to server and send email
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()  # Upgrade connection to secure
        server.login(sender_email, your_smtp_password)
        
        # Send email to BOTH sender and receiver as requested
        recipients = [sender_email, receiver_email]
        server.sendmail(sender_email, recipients, msg.as_string())
        server.quit()
        print("[EMAIL] Status email dispatched successfully.")
    except Exception as e:
        print(f"[EMAIL ERROR] Failed to send email: {e}")

